// Clean template blocks to pages.create input shape.
// Strip read-only metadata and null fields (Notion input API rejects nulls).
const SAFE = new Set(['paragraph','heading_1','heading_2','heading_3','to_do','bulleted_list_item','numbered_list_item','callout','quote','divider','toggle']);

function stripNulls(obj) {
  if (Array.isArray(obj)) return obj.map(stripNulls);
  if (obj && typeof obj === 'object') {
    const out = {};
    for (const k of Object.keys(obj)) {
      if (obj[k] === null) continue;
      out[k] = stripNulls(obj[k]);
    }
    return out;
  }
  return obj;
}

function cleanBlock(b) {
  const t = b.type;
  if (!SAFE.has(t)) return null;
  const body = stripNulls(Object.assign({}, b[t] || {}));
  return { object: 'block', type: t, [t]: body };
}

const blocks = ($input.first().json.results || [])
  .map(cleanBlock)
  .filter(x => x !== null);

// Pass through the Project row context from the trigger so the next node
// can reference it alongside the cleaned blocks.
const project = $('Notion: new Project').first().json;

return [{
  json: {
    projectId: project.id,
    projectName: (project.properties['Project Name'].title[0] || {}).plain_text || '',
    templateChildren: blocks,
  },
}];

